const assert=require('assert/strict');
const mirror='light-deep-lv4-mirror',amp='light-deep-lv4-amplification',reward='light-deep-lv2-imbalance';
module.exports=function audit(s,route){
 const boss='monster:5:1',bossStart=s.RoundTrace.find(t=>t.Data.Events.some(e=>e.Monster===boss)).Data.RoundNumber-1;
 const facts=s.MonsterPhaseRounds.filter(p=>p.MonsterId===5),last=facts.at(-1);
 const phaseFacts=new Map(facts.map(p=>[bossStart+p.LocalRound-1,p]));
 const mins=Array(5).fill(100),cycles=[],weakens=[],reflects=[],rewards=[],starts={};
 let active=null;
 function finish(r,kind){assert(active,'Finish requires live mirror');active.EndRound=r;active.Result=kind;active.FinalStrength=active.Strength;
  if(['DarkBreak','Dispel'].includes(kind)){active.BreakWindowRound=r-active.StartRound+1;active.ExpectedRewardStart=r+1;}
  active=null;
 }
 for(const [ti,t]of s.RoundTrace.entries()){
  const r=t.Data.RoundNumber-1,perActor=new Map(),used=new Set();
  assert(t.Data.OperationPotions.every(p=>!p.ItemCode));assert.equal(t.Data.ConsumableBuffs.length,0);
  for(const e of t.Data.Events){
   if(starts[e.Monster]===undefined)starts[e.Monster]=r;
   if(e.Target?.startsWith('character:')&&e.HpAfter!==null&&e.TargetMaxHp>0)mins[+e.Target.split(':')[1]-1]=Math.min(mins[+e.Target.split(':')[1]-1],100*e.HpAfter/e.TargetMaxHp);
   if(e.Source===boss&&e.ActionKind===0&&['light-deep-lv1-warden-pierce','light-deep-lv1-warden-nova'].includes(e.SkillCode)&&!(e.Kind===2&&[2,3,4].includes(e.StatusChange))){
    const local=r-bossStart+1,first=e.SkillCode.endsWith('pierce')?2:4;assert(local>=first);
    const previous=s.RoundTrace[ti-1]?.Data.MonsterCooldowns.find(c=>c.Actor===boss&&c.SkillCode===e.SkillCode);
    if(previous)assert(r>=previous.ReadyAtRound);
    assert.equal(t.Data.MonsterCooldowns.find(c=>c.Actor===boss&&c.SkillCode===e.SkillCode)?.ReadyAtRound,r+4);
   }
   assert(!(e.Source===boss&&e.SkillCode==='light-deep-lv1-warden-ward'));
   assert(!e.SkillCode?.startsWith('depth-placeholder-')&&!e.SkillCode?.startsWith('endgame-'));
   if(e.Status?.Code===mirror&&e.StatusChange===0){
    assert(!active);assert.equal(r-bossStart+1,6+cycles.length*10);assert.equal(e.CountAfter,6);
    assert.equal(e.Status.AppliedRound,r);assert.equal(e.Status.ExpiresAfterRound,r+3);
    active={StartRound:r,LocalStartRound:r-bossStart+1,ExpiresAfterRound:r+3,InitialStrength:6,Strength:6,Level:0,LinkedHits:0,Growth:[],EndRound:null,Result:null};cycles.push(active);
   }
   if(e.Status?.Code===mirror&&e.StatusChange===1)assert(active&&e.CountAfter<=active.Strength,'No strength regeneration');
   if(e.Status?.Code===mirror&&e.StatusChange===2){
    assert(active);const before=t.Data.Events.findLast(x=>x.Sequence<e.Sequence&&x.Kind===0&&x.Source===e.Source);
    assert(before&&before.Element===5&&before.ActualAmount>0&&before.Target===boss);assert([0,1,3,6].includes(before.ActionKind));
    assert(!used.has(e.Source));used.add(e.Source);assert.equal(e.CountBefore-e.CountAfter,1);assert.equal(e.CountBefore,active.Strength);
    active.Strength=e.CountAfter;active.LinkedHits++;
    weakens.push({Round:r,Actor:e.Source,StrengthAfter:e.CountAfter});
    if(active.Strength===0)finish(r,'DarkBreak');
   }
   if(e.Kind===4&&e.Status?.Code===mirror){assert.equal(e.SkillCode,'mage-spellbreak');assert(active);active.Strength=0;finish(r,'Dispel');}
   if(e.Status?.Code===mirror&&e.StatusChange===4&&active){
    assert.equal(r,active.ExpiresAfterRound);
    if(phaseFacts.get(r)?.LastExpiryRound===r)finish(r,'NaturalExpiry');
   }
   if(e.Status?.Code===amp&&[0,1].includes(e.StatusChange)){
    assert(active&&active.Strength>0);assert.equal(e.CountAfter,active.Level+1);
    assert.equal(e.CountAfter,r-active.StartRound+1);assert(e.CountAfter<=3);
    active.Level=e.CountAfter;assert.equal(e.Status.ExpiresAfterRound,active.ExpiresAfterRound);assert.equal(e.Status.CanDispel,false);assert.equal(e.Status.EffectType,'None');
    active.Growth.push({Round:r,Level:e.CountAfter,RemainingStrength:active.Strength});
   }
   if(e.Status?.Code===reward&&e.StatusChange===0){
    const prior=cycles.findLast(c=>c.ExpectedRewardStart===r);assert(prior,'Reward follows successful cycle');
    assert.equal(e.Status.ExpiresAfterRound,r+2);rewards.push({Round:r,ExpiresAfterRound:r+2});prior.Reward={StartRound:r,ExpiresAfterRound:r+2};
   }
   if(e.SkillCode==='light-reflection'&&e.Kind===0){
    assert.equal(e.Source,boss);assert.equal(e.ActionKind,6);assert.equal(e.Element,null);assert.equal(e.ElementModifier,0);assert.equal(e.IsCritical,false);
    assert(active&&active.Strength>0&&r>=active.StartRound&&r<=active.ExpiresAfterRound);assert.equal(active.Level,r-active.StartRound);
    const total=(perActor.get(e.Target)??0)+e.CalculatedAmount;perActor.set(e.Target,total);
    const hp=s.Builds[+e.Target.split(':')[1]-1].Stats.MaxHp;assert(total<=Math.floor(hp*6*(3+active.Level)/100),'Reflection within current-round initial raw ceiling');
    reflects.push({Round:r,Actor:e.Target,Amount:e.ActualAmount,Strength:active.Strength,Level:active.Level});
   }
  }
  if(active&&t.Data.Monsters.find(m=>m.Actor===boss)?.Hp===0)finish(r,'BossDeath');
  if(!active&&r>=bossStart)assert(!t.Data.Statuses.some(v=>v.Target===boss&&[mirror,amp].includes(v.EffectCode)),'Both statuses cleaned');
 }
 if(active){assert(!s.Victory,'Only defeat may leave an incomplete live phase');finish(s.RoundTrace.at(-1).Data.RoundNumber-1,'PartyDefeat');}
 assert.equal(cycles.length,last.Activations);assert.equal(cycles.filter(c=>['DarkBreak','Dispel'].includes(c.Result)).length,last.Breaks);
 assert.equal(cycles.filter(c=>c.Result==='NaturalExpiry').length,last.Expiries);assert.equal(weakens.length,last.LinkedHits);
 for(const c of cycles){
  if(c.Result==='NaturalExpiry'){assert.deepEqual(c.Growth.map(g=>g.Level),[1,2,3]);assert.equal(c.EndRound,c.StartRound+3);assert(!c.Reward);}
  if(['DarkBreak','Dispel'].includes(c.Result)){
   assert.equal(c.Growth.length,c.BreakWindowRound-1);
   if(c.ExpectedRewardStart<=s.RoundTrace.at(-1).Data.RoundNumber-1)assert(c.Reward,'Reward appears next complete round');
   if(route==='dark'){assert.equal(c.LinkedHits,6);assert.equal(c.BreakWindowRound,2);}
   if(route==='double'){assert.equal(c.LinkedHits,6);assert.equal(c.BreakWindowRound,3);}
  }
  if(route.startsWith('dispel')||route==='unhandled')assert.equal(c.LinkedHits,0);
  if(route==='single'||route==='unhandled')assert(!['DarkBreak','Dispel'].includes(c.Result));
 }
 return {BossStartRound:bossStart,Cycles:cycles.map(({Strength,Level,...c})=>c),Activations:last.Activations,Breaks:last.Breaks,NaturalExpiries:last.Expiries,
  LinkedHits:last.LinkedHits,WeakeningActions:weakens,Rewards:rewards,ReflectionEvents:reflects.length,ReflectedDamage:reflects.reduce((n,e)=>n+e.Amount,0),
  ReflectedDamageBySlot:Array.from({length:5},(_,i)=>reflects.filter(e=>e.Actor==='character:'+(i+1)).reduce((n,e)=>n+e.Amount,0)),MinimumHpPercentBySlot:mins,
  FixedLocalSchedule:true,FreshSixStacksAndZeroGrowthEveryCycle:true,GrowthDoesNotRepairStrength:true,PerActorDarkDedup:true,
  NextRoundThreeRoundRewards:true,NoReflectionAfterClear:true,CurrentRoundRawCeiling:true,NoLegacyWardPlaceholderOrEnrage:true};
};
